import{_ as o,C as s,o as i,c as r,aj as e,E as n}from"./framework.js";const u=JSON.parse('{"title":"Parameter Config | Content | Admin CMS","description":"Parameter config defines a set of structured key-value parameters for the site: design Schema (field names, display names, types) in the admin, then fill Data on another page; templates…","frontmatter":{"title":"Parameter Config | Content | Admin CMS","description":"Parameter config defines a set of structured key-value parameters for the site: design Schema (field names, display names, types) in the admin, then fill Data on another page; templates…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/content/user-options.html"}]]},"headers":[],"relativePath":"cms/content/user-options.md","filePath":"en/cms/content/user-options.md","lastUpdated":1781010536000}'),d={name:"cms/content/user-options.md"};function c(l,t,p,g,h,m){const a=s("DocImage");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="parameter-config" tabindex="-1">Parameter Config <a class="header-anchor" href="#parameter-config" aria-label="Permalink to &quot;Parameter Config&quot;">​</a></h1><blockquote><p>Menu: <strong>Content → Parameter config</strong> (route <code>useroptions</code>; must be enabled in <strong>Edit Menu</strong>)<br> Deep link: <code>/_Admin/content/useroptions?SiteId={siteGuid}</code></p></blockquote><p><strong>Parameter config</strong> defines a set of <strong>structured key-value parameters</strong> for the site: design <strong>Schema</strong> (field names, display names, types) in the admin, then fill <strong>Data</strong> on another page; templates and KScript read via <strong><code>k.paramConfig</code></strong> for site-level switches, header phone numbers, social link objects, etc. without embedding in Page source. API: <a href="/kb-docs/api/param-config/">k.paramConfig</a>.</p><div class="tip custom-block"><p class="custom-block-title">Difference from site custom settings and element attributes</p><table tabindex="0"><thead><tr><th></th><th><strong>Parameter config</strong> (this page)</th><th>Custom settings in site settings</th><th><a href="./tag-attributes.html">Element attributes</a></th></tr></thead><tbody><tr><td>Admin</td><td>Content → Parameter config</td><td>Site → Settings, etc.</td><td>Content → Element attributes</td></tr><tr><td>Data</td><td>JSON grouped by config name</td><td><code>k.site.info.setting</code>, etc.</td><td>KConfig: HTML attribute bindings</td></tr><tr><td>Templates</td><td><code>k.paramConfig.configName.field</code></td><td>Depends on site settings</td><td><code>k-config=&quot;key&quot;</code></td></tr><tr><td>Source</td><td>Create here + fill form</td><td>Not this menu</td><td>Auto-generated from template markers</td></tr></tbody></table></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, check <strong>Parameter config</strong>.</li><li>Open <strong>Content → Parameter config</strong> in the left sidebar.</li></ol>',6)),n(a,{src:"/cms/content/user-options-list.png",alt:"Parameter config list",width:"1120"}),t[1]||(t[1]=e('<h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column / action</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td>Display name or internal <strong>name</strong>; click to open <strong>Edit data</strong> (<code>useroptions/edit?id=...</code>)</td></tr><tr><td>Last modified</td><td>Update time</td></tr><tr><td><strong>Settings</strong> (gear)</td><td>Edit config <strong>Schema</strong> (field structure); requires <code>userOptions</code> · <code>setting</code></td></tr><tr><td>Batch delete</td><td>Delete selected rows (<code>userOptions</code> · <code>delete</code>)</td></tr></tbody></table><p>Toolbar <strong>New</strong> appears only with <strong>setting</strong> permission; opens <strong>Create</strong> page (name and Schema together).</p><h2 id="create-config" tabindex="-1">Create Config <a class="header-anchor" href="#create-config" aria-label="Permalink to &quot;Create Config&quot;">​</a></h2><p>Path: <code>/_Admin/content/useroptions/create?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Internal id, 1–50 chars, letter or digit start, unique in site; use <code>k.paramConfig.{name}</code> in templates</td></tr><tr><td><strong>Display name</strong></td><td>Admin display; optional</td></tr><tr><td><strong>Custom settings</strong></td><td>Schema editor: <strong>Name</strong>, <strong>Display</strong>, <strong>Type</strong> per field</td></tr></tbody></table><p>Schema <strong>types</strong>: text (<code>string</code>), number (<code>number</code>), boolean (<code>boolean</code>), object (<code>object</code>), array (<code>array</code>). Arrays need element type; objects and object arrays can nest sub-fields (indented on the left).</p><p>After save, returns to list; <strong>data</strong> is empty <code>{}</code> until you open <strong>Edit data</strong> from the list name link.</p>',8)),n(a,{src:"/cms/content/user-options-create.png",alt:"Create parameter config: name and Schema",width:"1120"}),t[2]||(t[2]=e('<h2 id="edit-schema-settings-page" tabindex="-1">Edit Schema (Settings Page) <a class="header-anchor" href="#edit-schema-settings-page" aria-label="Permalink to &quot;Edit Schema (Settings Page)&quot;">​</a></h2><p>From list row <strong>gear</strong>: <code>/_Admin/content/useroptions/setting?id=...</code></p><ul><li><strong>Name</strong> cannot change (avoids breaking <code>k.paramConfig.{name}</code> in templates).</li><li>Can change <strong>display name</strong> and <strong>Schema</strong> (add/remove fields, change types).</li><li>Saving Schema resets that config’s <strong>data to empty object</strong> <code>{}</code>; to keep values when adjusting structure, export JSON first (below) or re-enter after Schema changes.</li></ul>',3)),n(a,{src:"/cms/content/user-options-setting.png",alt:"Parameter config: edit Schema",width:"1120"}),t[3]||(t[3]=e('<h2 id="edit-data" tabindex="-1">Edit Data <a class="header-anchor" href="#edit-data" aria-label="Permalink to &quot;Edit Data&quot;">​</a></h2><p>From list <strong>name</strong> link: <code>/_Admin/content/useroptions/edit?id=...</code></p><p>Form rendered from Schema (text, number, switch, nested object, array, etc.). Top-right <strong>Edit code</strong> opens Monaco to edit the full <strong>JSON</strong> in bulk; confirm writes back to the form before save.</p><p>Save calls <code>updateOptions</code>; updates <strong>data</strong> only, not Schema.</p>',4)),n(a,{src:"/cms/content/user-options-edit.png",alt:"Parameter config: fill data per Schema",width:"1120"}),t[4]||(t[4]=e(`<h2 id="templates-and-kscript" tabindex="-1">Templates and KScript <a class="header-anchor" href="#templates-and-kscript" aria-label="Permalink to &quot;Templates and KScript&quot;">​</a></h2><p>Read saved site data (<code>data</code> field JSON):</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Assume config siteContact with Schema fields phone, showBanner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> phone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.phone;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> show </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.showBanner;</span></span></code></pre></div><ul><li>If config <strong>name</strong> does not exist or data is empty, properties are <strong>undefined</strong>.</li><li>Engine generates <strong>KDefine</strong> hints under <code>k.paramConfig</code> (per config and field names) for the script editor.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/kb-docs/api/param-config/">k.paramConfig</a> — KScript API</li><li><a href="./">Content overview</a></li><li><a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a></li><li><a href="./tag-attributes.html">Element attributes</a> (template <code>k-config</code>, not this page)</li></ul>`,6))])}const b=o(d,[["render",c]]);export{u as __pageData,b as default};
